-- GAF Planilla: full schema
CREATE TABLE IF NOT EXISTS schedules (
  id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  schedule_name TEXT NOT NULL,
  dst_start TEXT NOT NULL,
  dst_end TEXT NOT NULL,
  standard_start TEXT NOT NULL,
  standard_end TEXT NOT NULL,
  grace_minutes INT NOT NULL DEFAULT 10,
  notes TEXT,
  CONSTRAINT schedules_schedule_name_key UNIQUE (schedule_name)
);

CREATE TABLE IF NOT EXISTS dst_calendar (
  id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  year INT NOT NULL,
  us_dst_start DATE NOT NULL,
  us_dst_end DATE NOT NULL,
  CONSTRAINT dst_calendar_year_key UNIQUE (year)
);

CREATE TABLE IF NOT EXISTS holidays (
  id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  date DATE NOT NULL,
  name TEXT NOT NULL,
  CONSTRAINT holidays_date_key UNIQUE (date)
);

CREATE TABLE IF NOT EXISTS employees (
  id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  display_name TEXT NOT NULL,
  teramind_email TEXT NOT NULL,
  company_domain TEXT,
  schedule_id BIGINT REFERENCES schedules(id),
  is_grace_list BOOLEAN NOT NULL DEFAULT FALSE,
  is_macbook_swap BOOLEAN NOT NULL DEFAULT FALSE,
  excluded_from_payroll BOOLEAN NOT NULL DEFAULT FALSE,
  active BOOLEAN NOT NULL DEFAULT TRUE,
  start_date DATE,
  end_date DATE,
  notes TEXT,
  CONSTRAINT employees_teramind_email_key UNIQUE (teramind_email)
);

CREATE INDEX IF NOT EXISTS idx_employees_display_name ON employees (display_name);

CREATE TABLE IF NOT EXISTS name_aliases (
  id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  alias_text TEXT NOT NULL,
  employee_id BIGINT NOT NULL REFERENCES employees(id),
  CONSTRAINT name_aliases_alias_text_key UNIQUE (alias_text)
);

CREATE TABLE IF NOT EXISTS event_types (
  id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  name TEXT NOT NULL,
  CONSTRAINT event_types_name_key UNIQUE (name)
);

CREATE TABLE IF NOT EXISTS pay_impacts (
  id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  name TEXT NOT NULL,
  CONSTRAINT pay_impacts_name_key UNIQUE (name)
);

CREATE TABLE IF NOT EXISTS documentation_options (
  id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  name TEXT NOT NULL,
  CONSTRAINT documentation_options_name_key UNIQUE (name)
);

CREATE TABLE IF NOT EXISTS periods (
  id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  period_name TEXT NOT NULL,
  start_date DATE,
  end_date DATE,
  processed_at TEXT,
  employee_count INT DEFAULT 0,
  day_count INT DEFAULT 0,
  green_count INT DEFAULT 0,
  yellow_count INT DEFAULT 0,
  red_count INT DEFAULT 0,
  notes TEXT,
  CONSTRAINT periods_period_name_key UNIQUE (period_name)
);

CREATE TABLE IF NOT EXISTS run_snapshots (
  id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  period_name TEXT NOT NULL,
  snapshot_type TEXT NOT NULL,
  raw_data TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS payroll_entries (
  id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  period_name TEXT NOT NULL,
  employee_id BIGINT NOT NULL REFERENCES employees(id),
  work_date TEXT NOT NULL,
  entry_time TEXT,
  exit_time TEXT,
  scheduled_start TEXT,
  grace_until TEXT,
  scheduled_end TEXT,
  late_minutes INT DEFAULT 0,
  late_after_grace INT DEFAULT 0,
  early_leave_minutes INT DEFAULT 0,
  discount_total_minutes INT DEFAULT 0,
  payroll_ready TEXT DEFAULT 'NO',
  event_type_1 TEXT DEFAULT '',
  pay_impact_1 TEXT DEFAULT '',
  event_type_2 TEXT DEFAULT '',
  pay_impact_2 TEXT DEFAULT '',
  documentation TEXT DEFAULT '',
  notes TEXT DEFAULT '',
  auto_notes TEXT DEFAULT '',
  initial_status TEXT NOT NULL DEFAULT 'GREEN',
  status_current TEXT NOT NULL DEFAULT 'GREEN',
  resolved_by TEXT,
  resolved_at TIMESTAMPTZ,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  CONSTRAINT payroll_entries_period_employee_date_key UNIQUE (period_name, employee_id, work_date)
);

CREATE INDEX IF NOT EXISTS idx_payroll_entries_period ON payroll_entries (period_name);
CREATE INDEX IF NOT EXISTS idx_payroll_entries_employee ON payroll_entries (employee_id);
CREATE INDEX IF NOT EXISTS idx_payroll_entries_status ON payroll_entries (status_current);


